def scene_index(params: dict) -> str:
    return "<h1>Web Game</h1><p>Try /game?door=left or door=right</p>"


def scene_game(params: dict) -> str:
    door = params.get("door", "")
    if door == "left":
        return "<p>You find a quiet library. Safe for now.</p>"
    if door == "right":
        return "<p>A dragon snorts. Maybe go left next time.</p>"
    return "<p>Pick a door via ?door=left|right</p>"


ROUTES = {
    "/": scene_index,
    "/game": scene_game,
}


def dispatch(path: str, params: dict | None = None) -> str:
    params = params or {}
    print(f"[REQ] GET {path} {params}")
    handler = ROUTES.get(path)
    if not handler:
        body = f"<p>404 {path}</p>"
    else:
        body = handler(params)
    print("[RES]", body)
    return body


dispatch("/")
dispatch("/game", {"door": "left"})
dispatch("/game", {"door": "right"})
dispatch("/nope")
